const items = $input.all().map(i => i.json);
const sevenDaysAgo = Date.now() - 7 * 24 * 60 * 60 * 1000;

const recent = items.filter(item => {
  const d = new Date(item.pub_date);
  return !isNaN(d.getTime()) && d.getTime() > sevenDaysAgo;
});

function toRFC2822(dateStr) {
  return new Date(dateStr).toUTCString();
}

function escapeXml(str) {
  return String(str || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

const itemsXml = recent.map(item => {
  const imgTag = item.featured_image_url
    ? `\n    <enclosure url="${escapeXml(item.featured_image_url)}" type="image/jpeg" length="0"/>`
    : '';
  return `  <item>\n    <title>${escapeXml(item.title)}</title>\n    <guid isPermaLink="false">${escapeXml(item.guid)}</guid>\n    <pubDate>${toRFC2822(item.pub_date)}</pubDate>\n    <description><![CDATA[${item.body_html || ''}]]></description>${imgTag}\n  </item>`;
}).join('\n');

const xml = `<?xml version="1.0" encoding="UTF-8"?>\n<rss version="2.0">\n  <channel>\n    <title>StackSignal</title>\n    <link>https://stacksignal.news</link>\n    <description>Weekly signal for indie operators automating their stack</description>\n${itemsXml}\n  </channel>\n</rss>`;

return [{ json: { xml, itemCount: recent.length } }];
